.product-card {
  width: 160px; height: 220px;
  background: linear-gradient(135deg, #2a2a35, #15151e);
  border: 2px solid #333; border-radius: 15px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.8);
  display: flex; align-items: center; justify-content: center;
  color: #888; font-family: sans-serif; font-weight: bold;
  transform-style: preserve-3d; cursor: grab;
}
.product-card:active { cursor: grabbing; }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;perspective:800px;';

const card = document.createElement('div');
card.className = 'product-card';
card.innerText = 'SWIPE ME';
c.appendChild(card);

let isDragging = false;
let startX, startY, rotX = 0, rotY = 0;

card.addEventListener('pointerdown', (e) => {
  isDragging = true;
  startX = e.clientX; startY = e.clientY;
  card.style.transition = 'none';
});

document.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const deltaX = e.clientX - startX;
  const deltaY = e.clientY - startY;
  rotY += deltaX * 0.5; rotX -= deltaY * 0.5;
  card.style.transform = `rotateX(${rotX}deg) rotateY(${rotY}deg)`;
  startX = e.clientX; startY = e.clientY;
});

document.addEventListener('pointerup', () => {
  if(isDragging) {
    isDragging = false;
    card.style.transition = 'transform 0.5s ease';
    card.style.transform = `rotateX(0deg) rotateY(0deg)`;
    rotX = 0; rotY = 0;
  }
});
